<template><div class="login-page flex flex-center"><q-card class="login-card"><div class="login-card__brand"><img :src="logo" alt="BotBuilder Logo" class="login-card__logo" /><h1 class="login-card__title">สร้างบัญชี</h1><p class="login-card__subtitle">กรอกข้อมูลเพื่อเชื่อมต่อกับข้อมูลการเรียนของบุตรหลาน</p></div><q-form class="login-card__form" @submit.prevent="submit"><q-input v-model="form.userName" label="ชื่อผู้ปกครอง" outlined dense :rules="[required]" /><q-input v-model="form.userEmail" type="email" label="อีเมล" outlined dense :rules="[required]" /><q-input v-model="form.userPhone" type="tel" label="เบอร์โทรศัพท์ (ไม่บังคับ)" outlined dense maxlength="15" :rules="[phoneRule]"><template #prepend><q-icon name="phone" /></template></q-input><q-select v-model="form.guardianRelation" label="ความสัมพันธ์กับเด็ก" outlined dense emit-value map-options :options="guardianRelationOptions" :rules="[required]"><template #prepend><q-icon name="family_restroom" /></template></q-select><q-input v-model="form.childAccessCode" label="รหัสเข้าดูผลบุตรหลาน" outlined dense maxlength="8" hint="ขอรหัสนี้ได้จากเจ้าหน้าที่" :rules="[accessCodeRule]" @update:model-value="form.childAccessCode = form.childAccessCode.toUpperCase()"><template #prepend><q-icon name="vpn_key" /></template></q-input><q-input v-model="form.password" :type="showPassword ? 'text' : 'password'" label="รหัสผ่าน (อย่างน้อย 8 ตัวอักษร)" outlined dense :rules="[passwordRule]"><template #prepend><q-icon name="lock" /></template><template #append><q-icon :name="showPassword ? 'visibility_off' : 'visibility'" class="cursor-pointer" @click="showPassword = !showPassword" /></template></q-input><q-banner v-if="errorMessage" dense rounded class="login-card__error">{{ errorMessage }}</q-banner><q-btn type="submit" color="primary" unelevated no-caps label="สร้างบัญชี" :loading="loading" class="login-card__submit" /><p class="login-card__switch">มีบัญชีอยู่แล้ว? <RouterLink to="/login">เข้าสู่ระบบ</RouterLink></p></q-form></q-card></div></template>
<script setup lang="ts">
import { reactive, ref } from 'vue'; import { RouterLink, useRouter } from 'vue-router'; import axios from 'axios'; import logo from '@/assets/landing/logo.png'; import { useAuthStore } from '@/stores/auth-store';
type GuardianRelation = 'FATHER' | 'MOTHER' | 'GUARDIAN' | 'OTHER';
type RegisterForm = { userName: string; userEmail: string; userPhone: string; guardianRelation: GuardianRelation | ''; password: string; childAccessCode: string; };
const router = useRouter(); const auth = useAuthStore(); const form = reactive<RegisterForm>({ userName: '', userEmail: '', userPhone: '', guardianRelation: '', password: '', childAccessCode: '' }); const guardianRelationOptions = [{ label: 'บิดา', value: 'FATHER' }, { label: 'มารดา', value: 'MOTHER' }, { label: 'ผู้ปกครอง', value: 'GUARDIAN' }, { label: 'อื่น ๆ', value: 'OTHER' }]; const loading = ref(false); const showPassword = ref(false); const errorMessage = ref(''); const required = (value: string) => !!value || 'กรุณากรอกข้อมูล'; const phoneRule = (value: string) => !value || /^[0-9+()\-\s]{9,15}$/.test(value) || 'กรุณากรอกเบอร์โทรศัพท์ให้ถูกต้อง'; const accessCodeRule = (value: string) => /^[A-Z0-9]{8}$/.test(value) || 'กรุณากรอกรหัส 8 ตัวอักษร'; const passwordRule = (value: string) => value.length >= 8 || 'รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร';
async function submit(): Promise<void> { if (!form.userName || !form.userEmail || !form.guardianRelation || !/^[A-Z0-9]{8}$/.test(form.childAccessCode) || form.password.length < 8) return; loading.value = true; errorMessage.value = ''; try { await auth.register({ ...form, guardianRelation: form.guardianRelation }); await router.replace('/home'); } catch (error) { errorMessage.value = axios.isAxiosError(error) && error.response?.status === 400 ? 'กรุณาตรวจสอบข้อมูลที่กรอก' : axios.isAxiosError(error) && error.response?.status === 409 ? 'อีเมลนี้ถูกใช้แล้ว' : 'สมัครสมาชิกไม่สำเร็จ กรุณาลองใหม่'; } finally { loading.value = false; } }
</script>
